Translate("esMX", "zanzil-the-outcast", {
	title = "Zanzil el Proscrito",
	subtitle = "El médico brujo desterrado",
	found = "Las Ruinas de Aboraz, en La Costa de Cristal",
	hint = [=[Busque al médico brujo proscrito en las ruinas al noreste de Bahía del Botín.]=],
	allegiance = "Sus propios seguidores",
	aliases = { "Zanzil" },
	sections = {
		{
			title = "Resumen",
			text = [=[Zanzil es un médico brujo trol al que su propia tribu expulsó. Sus líderes le temían, y con razón. Sabe cómo doblegar la mente de otros. Con las plantas de la selva prepara una mezcla que apaga la voluntad de quienes la beben y fortalece su cuerpo, y sus seguidores de las {link:ruins-of-aboraz-and-jubuwal}Ruinas de Aboraz{/link} y de Jubuwal viven de ella. Puede que los muertos que vagan por allí también le deban su estado.]=],
		},
		{
			title = "Importancia",
			text = [=[El arte de Zanzil se ha extendido más allá de la selva. Los goblins de {link:booty-bay}Bahía del Botín{/link} compran muestras de su mezcla, y uno de ellos ha aprendido a convertirla en una bebida fuerte para sus propios planes. Muy al norte, los espías del {link:si-7}SI:7{/link} han averiguado que los trols de Zanzil saben cómo alzar a los muertos con veneno, y que el secreto ha pasado a manos de la {link:defias-brotherhood}Hermandad Defias{/link}. En {link:tarren-mill}Molino Tarren{/link}, {link:serge-hinott}Serge Hinott{/link} ha estudiado la locura que traen sus venenos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Fue desterrado por su tribu por su poder sobre otras mentes.
• Dirige a sus seguidores en las {link:ruins-of-aboraz-and-jubuwal}Ruinas de Aboraz{/link} y de Jubuwal.
• Se apoderó del muchacho {link:darkspear-trolls}Lanza Negra{/link} {link:yenniku}Yenniku{/link} y lo retuvo en cuerpo y alma.
• Se dice que sus brebajes alzan a los muertos.]=],
		},
	},
	chapters = {
		{
			title = "La mezcla",
			hint = "Arrebate a los seguidores de Zanzil el brebaje que los ata.",
			text = [=[{link:crank-fizzlebub}Crank Fizzlebub{/link} explicó el asunto con claridad a quienes quisieron escuchar. Una mezcla capaz de suprimir la voluntad y endurecer el cuerpo vale mucho para quienes quieren dominar a otros. Pagaba bien por ella, y un poco más por el silencio.]=],
		},
		{
			title = "El alma robada",
			hint = "Libere al joven Lanza Negra de las garras del médico brujo.",
			text = [=[El dominio de Zanzil sobre {link:yenniku}Yenniku{/link} era tan fuerte que solo la magia más potente podía romperlo. Los médicos brujos de los {link:darkspear-trolls}Lanza Negra{/link} hicieron esa magia con la joya de un {link:ogres}ogro{/link}. Cuando la gema de alma se cerró sobre el espíritu de Yenniku, Zanzil perdió al más preciado de sus esclavos.]=],
		},
	},
	mentions = {
		{ text = "El secreto de Zanzil" },
		{ text = "El destino de {link:yenniku}Yenniku{/link}" },
		{ text = "Salvar a {link:yenniku}Yenniku{/link}" },
		{ text = "De vuelta a {link:booty-bay}Bahía del Botín{/link}" },
		{ text = "La mezcla de Zanzil y una cerveza para necios" },
		{ text = "Deudas vudú" },
		{ text = "La torre de Klaven" },
	},
	bonds = {
		{ id = "yenniku", name = "Yenniku", note = "su esclavo" },
		{ id = "crank-fizzlebub", name = "Crank Fizzlebub", note = "compra su mezcla" },
		{ id = "nimboya", name = "Nimboya", note = "quiere arrebatarle a Yenniku" },
		{ id = "agent-kearnen", name = "Agente Kearnen", note = "descubrió el rastro del veneno" },
		{ id = "serge-hinott", name = "Serge Hinott", note = "cura su veneno" },
	},
})

Translate("esMX", "fleet-master-seahorn", {
