		},
	},
	mentions = {
		{ text = "Los Bucaneros Velasangre" },
		{ text = "Los Bucaneros Velasangre" },
		{ text = "Los Bucaneros Velasangre" },
		{ text = "Tesoro hundido" },
		{ text = "Tesoro hundido" },
	},
	bonds = {
