	sections = {
		{
			title = "Resumen",
			text = [=[Drizzlik es un peletero goblin que se proclama el mejor de los Mares del Sur y de los mundos viejo y nuevo. Sus botas Excelsior son su orgullo. El inventor jefe de la Unión de Manitas, el director Riddlevox, ha encargado una docena de pares, y nadie hace esperar a Riddlevox. Drizzlik forra las botas con piel de crocolisco y las ablanda con sangre de tigre. Para la capa exterior solo quiere la piel de un crocolisco de agua salada anciano. Ha oído que esas bestias se están extinguiendo, y eso le preocupa por su oficio.]=],
