Translate("esMX", "barnil-stonepot", {
	title = "Barnil Stonepot",
	subtitle = "Compañero de Nesingwary",
	found = "Expedición de Nesingwary",
	hint = [=[Hable con el enano que recibe a los visitantes del campamento de Nesingwary.]=],
	allegiance = "Expedición de Nesingwary",
	aliases = { "Barnil" },
	sections = {
		{
			title = "Resumen",
			text = [=[Barnil Stonepot es un {link:dwarves}enano{/link} del grupo de caza de {link:hemet-nesingwary}Hemet Nesingwary{/link}, y es quien recibe a los recién llegados al campamento. Habla de Hemet con abierta admiración. Hemet le confió la revisión del manuscrito de su libro, {i}{link:green-hills-of-stranglethorn}Green Hills of Stranglethorn{/link}{/i}. Entonces una ráfaga de viento barrió el campamento y esparció las páginas por la selva. Barnil recuperó la mayoría. El resto lo va reuniendo capítulo a capítulo, y teme el día en que Hemet se entere.]=],
		},
	},
	mentions = {
