	found = "Campamento Grom'gol",
	hint = "Hable con el médico brujo Lanza Negra de Grom'Gol.",
	allegiance = "Trols Lanza Negra · Horda",
	sections = {
		{
			title = "Resumen",
			text = [=[Se dice que Kin'weelay es el médico brujo más poderoso de los {link:darkspear-trolls}Lanza Negra{/link}. Vino a {link:grom-gol-base-camp}Grom'Gol{/link} para ayudar a {link:nimboya}Nimboya{/link}, pero tiene sus propios motivos para estar aquí. Libra la vieja guerra de la tribu contra los Cabellesangre y los Machacacráneos con trofeos y maldiciones. Buscó el Ojo de la Mente con la ayuda de los espíritus de la selva y lo transformó en una gema de alma. Habla con los espíritus de los muertos, y la {link:horde}Horda{/link} le trae cabezas cuyos secretos quiere conocer. Se ha llevado del {link:the-vile-reef}Arrecife Mortal{/link} un fragmento de la tablilla de Gri'lek para un santuario de {link:orgrimmar}Orgrimmar{/link}. Se dice que también ha puesto por escrito en lengua zandali la historia de una ciudad trol ahogada, la que ahora ha resurgido como {link:the-drowned-city}The Drowned City{/link}.]=],
		},
	},
	mentions = {
		{ text = "Los cristales cantores" },
		{ text = "El Ojo de la Mente" },
		{ text = "Collares de hueso ensangrentados" },
		{ text = "Collar de hueso partido" },
		{ text = "{link:the-vile-reef}El Arrecife Mortal{/link}" },
		{ text = "El médico brujo trol" },
	},
	bonds = {
		{ id = "nimboya", name = "Nimboya", note = "el enviado junto al que sirve" },
		{ id = "mai-zoth", name = "Mai'Zoth", note = "un viejo enemigo" },
